function claimRewards(uint256 tokenId, address recipient) external nonReentrant returns (uint256 rewards) {
    // Bond holder OR package owner (DETF diamond orchestrating holder claim).
    address owner = ERC721Repo._ownerOf(tokenId);
    DETFNFTVaultRepo.Storage storage layoutStruct = DETFNFTVaultRepo._layoutStruct();
    if (!DETFBondNFTMathLib._isCallerOwner(owner, msg.sender) && msg.sender != address(layoutStruct.detf)) {
        revert NotBondHolder(owner, msg.sender);
    }

    DETFNFTVaultRepo._updateGlobalRewards(layoutStruct);

    rewards = _harvestRewardsInternal(layoutStruct, tokenId, recipient);

    emit IDETFNFTVault.RewardsClaimed(tokenId, recipient, rewards);
}

/**
 * @dev Internal function to harvest rewards for a position.
 *      Uses service library structs to avoid stack-too-deep.
 */
function _harvestRewardsInternal(DETFNFTVaultRepo.Storage storage layoutStruct_, uint256 tokenId_, address recipient_)
    internal
    returns (uint256 rewards_)
{
    // Build params struct to reduce stack usage (math fields only)
    DETFNFTVaultService.HarvestParams memory params = DETFNFTVaultService.HarvestParams({
        effectiveShares: layoutStruct_.effectiveSharesOf[tokenId_],
        rewardPerShares: layoutStruct_.rewardPerShares,
        paidPerShare: layoutStruct_.userRewardPerSharePaid[tokenId_]
    });

    //     // Calculate rewards using service
    DETFNFTVaultService.HarvestResult memory result = DETFNFTVaultService._calcHarvestRewards(params);

    if (!result.hasRewards) {
        return 0;
    }

    rewards_ = result.rewards;

    // Execute transfer using service
    DETFNFTVaultService._executeHarvestTransfer(layoutStruct_, tokenId_, recipient_, rewards_);
}

function _updateGlobalRewards(Storage storage layoutStruct_) internal {
    uint256 totalShares_ = layoutStruct_.totalShares;
    if (totalShares_ == 0) {
        return;
    }

    uint256 currentBalance = layoutStruct_.rewardToken.balanceOf(address(this));
    uint256 lastBalance = layoutStruct_.lastRewardTokenBalance;

    if (currentBalance > lastBalance) {
        uint256 newRewards = currentBalance - lastBalance;
        layoutStruct_.rewardPerShares += (newRewards * 1e18) / totalShares_;
        layoutStruct_.lastRewardTokenBalance = currentBalance;
    }
}

function _executeHarvestTransfer(
    DETFNFTVaultRepo.Storage storage layout_,
    uint256 tokenId_,
    address recipient_,
    uint256 rewards_
) internal {
    // Update paid amount
    layout_.userRewardPerSharePaid[tokenId_] = layout_.rewardPerShares;
    layout_.lastRewardTokenBalance -= rewards_;

    // Safe transfer - using low-level call to avoid stack issues
    _safeTransfer(layout_.rewardToken, recipient_, rewards_);
}

function sellPositionToDetfNft(uint256 tokenId, address seller, address rewardsRecipient)
    external
    onlyOwner
    nonReentrant
    returns (uint256 principalShares, uint256 rewardsClaimed)
{
    DETFNFTVaultRepo.Storage storage layoutStruct = DETFNFTVaultRepo._layoutStruct();

    // Cannot sell protocol NFT or standing reward ids 1–2 (D7 / D17).
    if (_isDETFNFT(tokenId) || _isStandingRewardNft(tokenId)) {
        revert DETFNFTRestricted(tokenId);
    }

    address owner = ERC721Repo._ownerOf(tokenId);
    if (owner != seller) {
        revert NotBondHolder(owner, seller);
    }

    principalShares = layoutStruct.originalSharesOf[tokenId];
    if (principalShares == 0) {
        revert PositionNotFound(tokenId);
    }

    {
        uint256 unlockTime = layoutStruct.unlockTimeOf[tokenId];
        if (block.timestamp < unlockTime) {
            revert BondNotMature(unlockTime);
        }
    }

    if (rewardsRecipient == address(0)) {
        rewardsRecipient = seller;
    }

    // Update + harvest rewards to recipient (per TASK.md).
    DETFNFTVaultRepo._updateGlobalRewards(layoutStruct);
    rewardsClaimed = _harvestRewardsInternal(layoutStruct, tokenId, rewardsRecipient);

    // Remove the sold position (burns bonus shares by removing effectiveShares).
    DETFNFTVaultRepo._removePosition(layoutStruct, tokenId);

    // Transfer principal-only shares into the protocol NFT position.
    DETFNFTVaultRepo._addToPosition(layoutStruct, layoutStruct.detfNFTId, principalShares);

    // Burn the sold bond NFT.
    ERC721Repo._layoutStruct().approvedForTokenId[tokenId] = msg.sender;
    ERC721Repo._burn(tokenId);

/// @notice D25: harvest + remove + burn a mature user bond. Does not credit id 0.
function retireMaturePosition(uint256 tokenId, address rewardsRecipient)
    external
    onlyOwner
    nonReentrant
    returns (uint256 originalShares, uint256 rewardsClaimed)
{
    if (_isDETFNFT(tokenId) || _isStandingRewardNft(tokenId)) {
        revert DETFNFTRestricted(tokenId);
    }
    DETFNFTVaultRepo.Storage storage layoutStruct = DETFNFTVaultRepo._layoutStruct();
    address owner_ = ERC721Repo._ownerOf(tokenId);
    if (owner_ == address(0)) revert PositionNotFound(tokenId);
    {
        uint256 unlockTime = layoutStruct.unlockTimeOf[tokenId];
        if (block.timestamp < unlockTime) {
            revert BondNotMature(unlockTime);
        }
    }
    if (rewardsRecipient == address(0)) rewardsRecipient = owner_;
    DETFNFTVaultRepo._updateGlobalRewards(layoutStruct);
    rewardsClaimed = _harvestRewardsInternal(layoutStruct, tokenId, rewardsRecipient);
    originalShares = layoutStruct.originalSharesOf[tokenId];
    if (originalShares == 0) revert PositionNotFound(tokenId);
    DETFNFTVaultRepo._removePosition(layoutStruct, tokenId);
    ERC721Repo._layoutStruct().approvedForTokenId[tokenId] = msg.sender;
    ERC721Repo._burn(tokenId);
}

function sellPositionToDetfNft(uint256 tokenId_, address recipient_)
    public
    virtual
    nonReentrant
    returns (uint256 principalShares_)
{
    _requireMature(tokenId_);
    _requireNotStandingRewardNft(tokenId_);
    UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
    if (recipient_ == address(0)) recipient_ = msg.sender;

    // D10: transfer originalShares to id 0. Physical LP stays on the NFT vault (D13).
    if (address(s.rebasingClaimToken) == address(0)) {
        principalShares_ = DETFBondLifecycleLib._sellPositionToDetfNft(
            IDetfSelfNftInventoryPolicy(address(s.bondNftVault)), tokenId_, msg.sender, recipient_
        );
    } else {
        (principalShares_,) = DETFBondLifecycleLib._sellPositionToRebasingClaim(
            IDetfSelfNftInventoryPolicy(address(s.bondNftVault)),
            s.rebasingClaimToken,
            tokenId_,
            msg.sender,
            recipient_
        );
    }
    UniswapV4SingleStandardExchangeDETFRepo._subUserBondedLp(principalShares_);
    _topUpFeeCreatorShares();
    _tryCompoundProtocolRewards();
}

function _sellPositionToRebasingClaim(
    IDetfSelfNftInventoryPolicy vault_,
    IRebasingClaimToken rebasingClaimToken_,
    uint256 tokenId_,
    address seller_,
    address recipient_
) internal returns (uint256 principalShares_, uint256 rebasingClaimMinted_) {
    uint256 protocolBefore_ = vault_.originalSharesOf(vault_.detfNFTId());
    principalShares_ = _sellPositionToDetfNft(vault_, tokenId_, seller_, recipient_);

    rebasingClaimMinted_ =
        rebasingClaimToken_.mintFromNFTSale(principalShares_, protocolBefore_, recipient_);
}

function _sellPositionToDetfNft(
    IDetfSelfNftInventoryPolicy vault_,
    uint256 tokenId_,
    address seller_,
    address recipient_
) internal returns (uint256 principalShares_) {
    uint256 unlockTime_ = vault_.unlockTimeOf(tokenId_);
    if (block.timestamp < unlockTime_) {
        revert BondNotMature(unlockTime_);
    }
    (principalShares_,) = vault_.sellPositionToDetfNft(tokenId_, seller_, recipient_);
}

function closeBondMature(
    uint256 tokenId_,
    uint256[] calldata minAmountsOut_,
    address recipient_,
    uint256 deadline_
) public virtual nonReentrant returns (uint256[] memory amountsOut_) {
    _requireMature(tokenId_);
    _requireNotStandingRewardNft(tokenId_);
    _requireActive(deadline_, 1);
    if (recipient_ == address(0)) recipient_ = msg.sender;

    UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
    if (minAmountsOut_.length != 2) {
        revert UniswapV4SingleStandardExchangeDETFRepo.InvalidRoute(IERC20(address(0)), IERC20(address(0)));
    }
    if (minAmountsOut_[0] != 0) {
        revert UniswapV4SingleStandardExchangeDETFRepo.InvalidRoute(IERC20(address(this)), IERC20(address(0)));
    }

    _realizeExpansionIfNeeded();

    uint256 lpOut_ = s.bondNftVault.convertToAssets(s.bondNftVault.originalSharesOf(tokenId_));
    if (lpOut_ == 0) revert UniswapV4SingleStandardExchangeDETFRepo.ZeroAmount();
    uint256 orig_ = s.bondNftVault.originalSharesOf(tokenId_);
    s.bondNftVault.retireMaturePosition(tokenId_, recipient_);
    UniswapV4SingleStandardExchangeDETFRepo._subUserBondedLp(orig_);

    _pullNftLp(lpOut_);
    (uint256 detfOut_, uint256 pairOut_) = _withdrawProportional(lpOut_);
    if (detfOut_ > 0) {
        uint256 lpRejoin_ = _depositSingleDetfUntilDust(detfOut_, _bondLpHolder());
        if (lpRejoin_ == 0) revert UniswapV4SingleStandardExchangeDETFRepo.ZeroAmount();
        s.bondNftVault.addToDETFNFT(s.bondNftVault.detfNFTId(), lpRejoin_);
        _topUpFeeCreatorShares();
    }
    if (pairOut_ < minAmountsOut_[1]) {
        revert UniswapV4SingleStandardExchangeDETFRepo.InvalidRoute(s.pairToken, IERC20(address(0)));
    }
    if (pairOut_ > 0) {
        s.pairToken.safeTransfer(recipient_, pairOut_);
    }

    amountsOut_ = new uint256[](2);
    amountsOut_[1] = pairOut_;

    _tryCompoundProtocolRewards();
    _syncAllExpectedHoldReserves();
}

function redeemClaim(
    uint256 claimAmount_,
    IERC20 tokenOut_,
    uint256 minOut_,
    address recipient_,
    uint256 deadline_
) public virtual nonReentrant returns (uint256 amountOut_) {
    amountOut_ = _redeemClaimForDetf(claimAmount_, tokenOut_, minOut_, recipient_, deadline_);
}

/// @dev D15: claim → DETF. Pending on id 0 first; leftover pending compounded; shortfall from LP.
function _redeemClaimForDetf(
    uint256 claimAmount_,
    IERC20 tokenOut_,
    uint256 minOut_,
    address recipient_,
    uint256 deadline_
) internal returns (uint256 amountOut_) {
    _requireReserveLive();
    _requireActive(deadline_, claimAmount_);
    if (recipient_ == address(0)) recipient_ = msg.sender;

    UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
    if (address(s.rebasingClaimToken) == address(0)) revert UniswapV4SingleStandardExchangeDETFRepo.ClaimTokenNotConfigured();
    if (address(tokenOut_) != address(this)) {
        revert UniswapV4SingleStandardExchangeDETFRepo.InvalidRoute(IERC20(address(s.rebasingClaimToken)), tokenOut_);
    }

    _realizeExpansionIfNeeded();

    uint256 lpOut_ = _burnClaimConvertToAssets(claimAmount_);
    uint256 owed_ = _previewZapOutToDetf(lpOut_);
    uint256 harvested_ = s.bondNftVault.reallocateDetfNftRewards(address(this));

    if (harvested_ >= owed_) {
        amountOut_ = owed_;
        uint256 leftover_ = harvested_ - owed_;
        if (leftover_ > 0) {
            uint256 lpBack_ = _depositSingleDetfCapped(leftover_, _bondLpHolder());
            if (lpBack_ > 0) {
                s.bondNftVault.addToDETFNFT(s.bondNftVault.detfNFTId(), lpBack_);
            }
        }
        if (lpOut_ > 0) {
            s.bondNftVault.addToDETFNFT(s.bondNftVault.detfNFTId(), lpOut_);
        }
    } else {
        _pullNftLp(lpOut_);
        amountOut_ = _fillRedeemShortfall(lpOut_, harvested_, owed_, deadline_);
    }

    if (amountOut_ < minOut_) {
        revert IStandardExchangeErrors.MinAmountNotMet(minOut_, amountOut_);
    }
    if (amountOut_ > 0) {
        IERC20(address(this)).safeTransfer(recipient_, amountOut_);
    }
    _topUpFeeCreatorShares();
    _syncAllExpectedHoldReserves();
}

function _burnClaimConvertToAssets(uint256 claimAmount_) private returns (uint256 lpOut_) {
    UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
    uint256 totalSharesBefore_ = s.rebasingClaimToken.totalShares();
    uint256 sharesBurned_ = s.rebasingClaimToken.burnShares(claimAmount_, msg.sender, false);
    if (sharesBurned_ == 0) revert UniswapV4SingleStandardExchangeDETFRepo.ZeroAmount();
    uint256 totalAssets_ = _protocolOriginalShares();
    uint256 totalShares_ = totalSharesBefore_ == 0 ? sharesBurned_ : totalSharesBefore_;
    lpOut_ = (sharesBurned_ * totalAssets_) / totalShares_;
    if (lpOut_ == 0) revert UniswapV4SingleStandardExchangeDETFRepo.ZeroAmount();
    s.bondNftVault.removeFromDETFNFT(s.bondNftVault.detfNFTId(), lpOut_);
}

function _burnDetfExactIn(
    uint256 detfIn_,
    IERC20 tokenOut_,
    uint256 minOut_,
    address recipient_,
    bool pretransferred_,
    uint256 /* deadline_ */
) internal returns (uint256 amountOut_) {
    _requireReserveLive();
    _realizeExpansionIfNeeded();
    if (!_isBurningAllowed()) {
        UniswapV4SingleStandardExchangeDETFRepo.Storage storage s0 = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
        revert UniswapV4SingleStandardExchangeDETFRepo.BurningNotAllowed(_syntheticPrice(), s0.burnThreshold);
    }
    if (recipient_ == address(0)) recipient_ = msg.sender;

    UniswapV4SingleStandardExchangeDETFRepo.Storage storage s = UniswapV4SingleStandardExchangeDETFRepo._layoutStruct();
    if (address(tokenOut_) != address(s.pairToken)) {
        revert UniswapV4SingleStandardExchangeDETFRepo.InvalidRoute(IERC20(address(this)), tokenOut_);
    }

    uint256 actualIn_ = _pullToken(IERC20(address(this)), detfIn_, pretransferred_);
    uint256 supply_ = ERC20Repo._totalSupply();
    uint256 nftLp_ = _nftLp();
    if (nftLp_ == 0 || supply_ == 0) revert UniswapV4SingleStandardExchangeDETFRepo.EmptyProtocolLp();

    uint256 lpOut_ = actualIn_ * nftLp_ / supply_;
    if (lpOut_ == 0) revert UniswapV4SingleStandardExchangeDETFRepo.EmptyProtocolLp();

    _burnDetf(address(this), actualIn_);
    _ensureProtocolLpOnDiamond(lpOut_);
    amountOut_ = _withdrawSinglePair(lpOut_, recipient_);

    if (amountOut_ < minOut_) {
        revert IStandardExchangeErrors.MinAmountNotMet(minOut_, amountOut_);
    }
    _syncAllExpectedHoldReserves();
}

function exchangeIn(
    IERC20 tokenIn_,
    uint256 amountIn_,
    IERC20 tokenOut_,
    uint256 minAmountOut_,
    address recipient_,
    bool pretransferred_,
    uint256 deadline_
) public virtual nonReentrant returns (uint256 amountOut_) {
    _requireActive(deadline_, amountIn_);
    if (address(tokenIn_) != address(this)) {
        _requireNotDisabled();
    }
    if (recipient_ == address(0)) recipient_ = msg.sender;

    if (address(tokenIn_) == address(this)) {
        return _burnDetfExactIn(amountIn_, tokenOut_, minAmountOut_, recipient_, pretransferred_, deadline_);
    }
    if (address(tokenOut_) == address(this)) {
        amountOut_ = _mintPath(tokenIn_, amountIn_, recipient_, pretransferred_, deadline_);
        if (amountOut_ < minAmountOut_) {
            revert IStandardExchangeErrors.MinAmountNotMet(minAmountOut_, amountOut_);
        }
        _syncAllExpectedHoldReserves();
        return amountOut_;
    }
    if (address(tokenIn_) != address(this)) {
        amountOut_ =
            _sePassthrough(tokenIn_, amountIn_, tokenOut_, minAmountOut_, recipient_, pretransferred_, deadline_);
        _syncAllExpectedHoldReserves();
        return amountOut_;
    }
    revert UniswapV4SingleStandardExchangeDETFRepo.InvalidRoute(tokenIn_, tokenOut_);

function mintFromNFTSale(uint256 assets, uint256 totalAssetsBefore, address recipient)
    public
    onlyOwner
    returns (uint256 rebasingClaimMinted)
{
    if (assets == 0) revert ZeroAmount();

    RebasingClaimTokenRepo.Storage storage layoutStruct = RebasingClaimTokenRepo._layoutStruct();
    uint256 totalAssets = totalAssetsBefore == type(uint256).max
        ? layoutStruct.nftVault.originalSharesOf(layoutStruct.detfNFTId)
        : totalAssetsBefore;
    uint256 totalSharesExt = RebasingClaimTokenRepo._internalSharesToExternal(layoutStruct.totalShares);
    uint256 sharesOutExt = totalAssets == 0 ? assets : (assets * totalSharesExt) / totalAssets;
    uint256 internalShares = RebasingClaimTokenRepo._externalSharesToInternal(sharesOutExt);

    RebasingClaimTokenRepo._mintShares(layoutStruct, recipient, internalShares);

    uint256 rate = _getCurrentRedemptionRate(layoutStruct);
    rebasingClaimMinted = RebasingClaimTokenRepo._sharesToBalance(internalShares, rate);

    emit IRebasingClaimToken.Minted(recipient, assets, sharesOutExt, rebasingClaimMinted);
    emit IERC20Events.Transfer(address(0), recipient, rebasingClaimMinted);

function _externalSharesToInternal(uint256 externalShares_) internal pure returns (uint256) {
    return externalShares_ * SHARE_SCALE;
}

/**
 * @notice Converts internal share units to external share units (floor).
 */
function _internalSharesToExternal(uint256 internalShares_) internal pure returns (uint256) {
    return internalShares_ / SHARE_SCALE;
}

/**
 * @notice Calculates the rebasing claim token balance from shares.
 * @dev balance = internalShares * redemptionRate / SHARE_UNIT
 */
function _sharesToBalance(uint256 internalShares_, uint256 redemptionRate_) internal pure returns (uint256) {
    return internalShares_.mulDiv(redemptionRate_, SHARE_UNIT);
}

/**
 * @notice Calculates shares from rebasing claim token balance.
 * @dev internalShares = balance * SHARE_UNIT / redemptionRate
 */
function _balanceToShares(uint256 balance_, uint256 redemptionRate_) internal pure returns (uint256) {
    if (redemptionRate_ == 0) return 0;
    return balance_.mulDiv(SHARE_UNIT, redemptionRate_);

function _balanceOf(address account) internal view returns (uint256) {
    RebasingClaimTokenRepo.Storage storage layoutStruct = RebasingClaimTokenRepo._layoutStruct();
    uint256 rate = _getCurrentRedemptionRate(layoutStruct);
    return RebasingClaimTokenRepo._sharesToBalance(layoutStruct.sharesOf[account], rate);
}

/**
 * @inheritdoc IRebasingClaimToken
 */
function sharesOf(address account) external view returns (uint256) {
    return RebasingClaimTokenRepo._internalSharesToExternal(RebasingClaimTokenRepo._sharesOf(account));
}

/**
 * @inheritdoc IRebasingClaimToken
 */
function totalShares() external view returns (uint256) {
    return RebasingClaimTokenRepo._internalSharesToExternal(RebasingClaimTokenRepo._totalShares());
}

/**
 * @inheritdoc IRebasingClaimToken
 */
function redemptionRate() external view returns (uint256) {
    return _getCurrentRedemptionRate(RebasingClaimTokenRepo._layoutStruct());
}

function redeem(uint256 rebasingClaimAmount, address recipient, bool pretransferred)
    external
    nonReentrant
    returns (uint256 wethOut)
{
    if (rebasingClaimAmount == 0) revert ZeroAmount();

    RebasingClaimTokenRepo.Storage storage layoutStruct = RebasingClaimTokenRepo._layoutStruct();
    uint256 actualIn = _secureTokenTransfer(IERC20(address(this)), rebasingClaimAmount, pretransferred);
    wethOut = _executeRedeem(layoutStruct, actualIn, recipient == address(0) ? msg.sender : recipient);
}

function _executeRedeem(RebasingClaimTokenRepo.Storage storage layoutStruct_, uint256 rebasingClaimAmount_, address recipient_)
    internal
    returns (uint256 wethOut_)
{
    uint256 rate = _getCurrentRedemptionRate(layoutStruct_);
    uint256 shares = RebasingClaimTokenRepo._balanceToShares(rebasingClaimAmount_, rate);

    if (layoutStruct_.sharesOf[address(this)] < shares) {
        revert InsufficientBalance(
            RebasingClaimTokenRepo._internalSharesToExternal(shares),
            RebasingClaimTokenRepo._internalSharesToExternal(layoutStruct_.sharesOf[address(this)])
        );
    }

    // 4626 convertToAssets against protocol NFT originalShares (before burn).
    uint256 bptOut_ = _convertInternalSharesToProtocolBpt(layoutStruct_, shares);
    if (bptOut_ == 0) revert ZeroAmount();

    // Burn claim shares first (CEI).
    RebasingClaimTokenRepo._burnShares(layoutStruct_, address(this), shares);

    // L-CLAIM-1/2: fund redeem by unwinding protocol NFT LP via DETF - not idle rateAsset inventory.
    wethOut_ = layoutStruct_.detf.claimLiquidity(bptOut_, recipient_);

    emit IRebasingClaimToken.Redeemed(
        msg.sender, recipient_, rebasingClaimAmount_, bptOut_, wethOut_
    );
    emit IERC20Events.Transfer(address(this), address(0), rebasingClaimAmount_);
}

function _secureTokenTransfer(IERC20 token_, uint256 amount_, bool pretransferred_) internal returns (uint256 actualIn_) {
    uint256 balanceBefore = token_.balanceOf(address(this));
    if (!pretransferred_) {
        if (address(token_) == address(this)) {
            _transfer(msg.sender, address(this), amount_);
        } else {
            token_.safeTransferFrom(msg.sender, address(this), amount_);
        }
    }
    uint256 observedDelta = token_.balanceOf(address(this)) - balanceBefore;
    if (pretransferred_) {
        if (amount_ > observedDelta) {
            revert ISecurePullErrors.TransferDeltaInsufficient(amount_, observedDelta);
        }
        // Credit exactly claimed; surplus delta is not credited (no exact-delta grief).
        return amount_;
    }
    // Self-token transfer is exact (share accounting); foreign may be FoT-short.
    if (address(token_) == address(this)) {
        return amount_;
    }
    return observedDelta;
}

function _calcCurrentRedemptionRate(RebasingClaimTokenRepo.Storage storage layoutStruct_) internal view returns (uint256 rate) {
    uint256 totalShares_ = layoutStruct_.totalShares;
    if (totalShares_ == 0) {
        return ONE_WAD;
    }

    uint256 zapout_ = _protocolNftZapOut(layoutStruct_);
    if (zapout_ == 0) {
        return ONE_WAD;
    }

    rate = Math.mulDiv(zapout_, RebasingClaimTokenRepo._shareUnit(), totalShares_);
    if (rate == 0) {
        rate = 1;
    }
}

/// @dev Zapout of the protocol bond NFT's whole reserve-LP slice (4626 assets, then single-sided exit).
function _protocolNftZapOut(RebasingClaimTokenRepo.Storage storage layoutStruct_)
    internal
    view
    returns (uint256 zapout_)
{
    if (layoutStruct_.totalShares == 0) return 0;
    uint256 orig_ = layoutStruct_.nftVault.originalSharesOf(layoutStruct_.detfNFTId);
    if (orig_ == 0) {
        IDETFNFTVault.Position memory position_ = layoutStruct_.nftVault.getPosition(layoutStruct_.detfNFTId);
        orig_ = position_.originalShares;
    }
    if (orig_ == 0) return 0;

    uint256 lp_ = orig_;
    try layoutStruct_.nftVault.convertToAssets(orig_) returns (uint256 assets_) {
        if (assets_ > 0) lp_ = assets_;
    } catch {}

    return _reserveShareZapOut(layoutStruct_, lp_);
}

/// @dev Canonical quote: DETF `previewClaimLiquidity` (reserve LP zapout). Fallback: previewExchangeIn.
function _reserveShareZapOut(RebasingClaimTokenRepo.Storage storage layoutStruct_, uint256 lpAmount_)
    internal
    view
    returns (uint256 zapout_)
{
    try layoutStruct_.detf.previewClaimLiquidity(lpAmount_) returns (uint256 z_) {
        return z_;
    } catch {
        IERC20 bpt = IERC20(layoutStruct_.detf.reservePool());
        return IStandardExchangeIn(address(layoutStruct_.detf)).previewExchangeIn(
            bpt, lpAmount_, layoutStruct_.rateAsset
        );
    }

function transfer(address recipient, uint256 amount) external returns (bool) {
    ERC20Repo._transfer(msg.sender, recipient, amount);
    return true;
}

function balanceOf(address account) external view returns (uint256) {
    return ERC20Repo._balanceOf(account);
}
